package com.aoo.bcg.common.room;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.security.SecureRandom;import java.time.Duration;import java.util.Locale;import java.util.Objects;
/** Unified human room code policy: 40-bit code space, collision reservation and reuse quarantine. */
public final class RoomCodePolicy{public static final String ALPHABET="23456789ABCDEFGHJKMNPQRSTUVWXYZ";public static final int LENGTH=8;private final SecureRandom random;private final RoomCodeStore store;private final AuthoritativeTimeSource time;private final Duration lifetime,reuseQuarantine;public RoomCodePolicy(SecureRandom random,RoomCodeStore store,AuthoritativeTimeSource time,Duration lifetime,Duration reuseQuarantine){this.random=Objects.requireNonNull(random);this.store=Objects.requireNonNull(store);this.time=Objects.requireNonNull(time);this.lifetime=lifetime;this.reuseQuarantine=reuseQuarantine;if(lifetime.isNegative()||lifetime.isZero()||reuseQuarantine.isNegative())throw new IllegalArgumentException("invalid room code lifetime");}public String issue(){for(int attempt=0;attempt<32;attempt++){StringBuilder value=new StringBuilder(LENGTH);for(int i=0;i<LENGTH;i++)value.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));var now=time.now();if(store.reserve(value.toString(),now,now.plus(lifetime),now.plus(lifetime).plus(reuseQuarantine)))return value.toString();}throw new IllegalStateException("room code collision budget exhausted");}public String normalize(String input){if(input==null)throw new IllegalArgumentException("room code required");String code=input.strip().toUpperCase(Locale.ROOT);if(code.length()!=LENGTH||code.chars().anyMatch(ch->ALPHABET.indexOf(ch)<0))throw new IllegalArgumentException("invalid room code");return code;}public boolean active(String input){return store.active(normalize(input),time.now());}}
